class Solution {
public:
    vector<vector<int>> findMissingRanges(vector<int>& nums, int lower, int upper) {
        vector<vector<int>> res;
        long long prev = static_cast<long long>(lower) - 1;
        int n = nums.size();
        for (int i = 0; i <= n; ++i) {
            long long curr = (i < n) ? nums[i] : static_cast<long long>(upper) + 1;
            if (curr - prev >= 2) {
                res.push_back({static_cast<int>(prev + 1), static_cast<int>(curr - 1)});
            }
            prev = curr;
        }
        return res;
    }
};

class Solution {
    public List<List<Integer>> findMissingRanges(int[] nums, int lower, int upper) {
        List<List<Integer>> res = new ArrayList<>();
        long prev = (long) lower - 1;
        int n = nums.length;
        for (int i = 0; i <= n; i++) {
            long curr = (i < n) ? nums[i] : (long) upper + 1;
            if (curr - prev >= 2) {
                res.add(Arrays.asList((int) (prev + 1), (int) (curr - 1)));
            }
            prev = curr;
        }
        return res;
    }
}

/**
 * @param {number[]} nums
 * @param {number} lower
 * @param {number} upper
 * @return {number[][]}
 */
var findMissingRanges = function(nums, lower, upper) {
    const res = [];
    let prev = lower - 1;
    const n = nums.length;
    for (let i = 0; i <= n; i++) {
        const curr = i < n ? nums[i] : upper + 1;
        if (curr - prev >= 2) {
            res.push([prev + 1, curr - 1]);
        }
        prev = curr;
    }
    return res;
};
